"💡 Это композитор Пётр Ильич Чайковский": "💡 这是作曲家彼得·伊里奇·柴可夫斯基",
"7 уроков: материалы, инструменты, измерение, приёмы работы, природные материалы, национальные узоры, выставка": "7 节课：材料、工具、测量、工作方法、天然材料、民族图案、展览",
"А эта полоска доходит до цифры 7. Её длина семь сантиметров.": "而这根纸条到数字 7。它的长度是七厘米。",
"В конце рассказывают о работе и показывают её на выставке.": "最后讲讲作品，并在展览上展示。",
"В природе берут только опавшее. Живые цветы и ветки трогать нельзя.": "在大自然中只捡掉落的东西。不能碰活的花和树枝。",
