"Жёлудь — плод дуба. Его можно использовать в поделках.": "橡子是橡树的果实。可以用在手工里。",
"Знать инструменты и безопасно с ними работать": "认识工具，安全地使用它们",
"Иглой с ниткой сшивают ткань. Иглу хранят в игольнице и не берут в рот.": "用针和线缝布。针要放在针插里，不能含在嘴里。",
"Идею ищут в книгах, на образцах изделий и у взрослых.": "可以在书里、成品样品上和向大人寻找想法。",
"Измерять длину линейкой и размечать детали": "用尺子量长度，并标出零件",
"Измерять линейкой начинают с нуля.": "用尺子量要从零开始。",
"Казахские мастера украшают вещи красивыми узорами. Давай познакомимся с ними. Нажимай на карточки.": "哈萨克工匠用漂亮的图案装饰物品。让我们来认识它们。点一点卡片。",
"Картон плотнее и прочнее бумаги. Из него делают основы для поделок.": "硬纸板比纸更厚实、更结实。用它做手工的底座。",
"Картонная коробка — тоже бросовый материал. Из неё получится домик или машина.": "纸箱也是废旧材料。可以做成小房子或汽车。",
"Клеем соединяют детали из бумаги и картона. Клей нельзя пробовать на вкус.": "用胶水粘合纸和硬纸板的部件。不能尝胶水的味道。",
"Кошма — войлочный ковёр. Её делают из овечьей шерсти.": "毡毯是毛毡地毯。用羊毛制成。",
"Лист — природный материал. Опавшие листья собирают и сушат между страницами книги.": "树叶是天然材料。把掉落的树叶收集起来，夹在书页里晾干。",
"Материалы бывают художественные, природные и искусственные.": "材料有美术材料、天然材料和人造材料。",
"Мягкость, твёрдость, прочность, цвет и форма — это свойства материала.": "柔软、坚硬、结实、颜色和形状是材料的特性。",
"На выставке показывают готовые работы.": "展览上展示做好的作品。",
"Национальную одежду тоже украшают узорами: тюбетейку, камзол и чапан.": "民族服装也用图案装饰：小圆帽、坎肩和恰潘。",
"Ножницами режут бумагу, картон и ткань. Передавать их надо кольцами вперёд.": "用剪刀剪纸、硬纸板和布。递剪刀时要把环形的把手朝前。",
