"Оригами: фигурки складывают из бумаги без ножниц и клея.": "折纸：不用剪刀和胶水，用纸折出小动物。",
"Орнамент — узор из повторяющихся элементов.": "纹样是由重复的元素组成的图案。",
"Перед работой готовят рабочее место. После работы убирают обрезки.": "工作前准备好工作位置。工作后清理碎屑。",
"Пластиковая бутылка — бросовый материал. Её моют и сушат перед работой.": "塑料瓶是废旧材料。工作前要洗净晾干。",
"Пластилин мягкий. Он легко меняет форму.": "橡皮泥很软。它很容易变形。",
"Поделки можно делать из того, что дарит природа, и из того, что обычно выбрасывают. Нажимай на карточки.": "手工可以用大自然赐予的东西来做，也可以用通常被扔掉的东西来做。点一点卡片。",
"Поделку можно сделать разными приёмами. Давай узнаем, как их выбрать и в каком порядке работать. Нажимай на карточки.": "手工可以用不同的方法做。让我们看看怎样选择，按什么顺序做。点一点卡片。",
"Поздравляю! Ты узнал про материалы и инструменты, измерение, приёмы работы, природные материалы и национальные узоры. Теперь можно придумать и сделать свою поделку!": "祝贺你！你了解了材料和工具、测量、工作方法、天然材料和民族图案。现在你可以构思并做出自己的手工了！",
"После работы нужно вымыть руки.": "工作后要洗手。",
"Потом размечают, вырезают и склеивают детали.": "然后标记、剪下并粘合部件。",
"Привет! Это Барсик. Из чего делают поделки? Из разных материалов. Нажимай на карточки и знакомься.": "你好！我是巴尔西克。手工是用什么做的？用各种材料。点一点卡片来认识它们。",
"Придумывать идею, показывать работу и вежливо оценивать": "想出创意，展示作品，并有礼貌地评价",
"Работа готова! Теперь её можно показать и услышать, что о ней думают. Нажимай на карточки.": "作品完成了！现在可以展示它，听听别人的想法。点一点卡片。",
"Различать материалы и сравнивать их свойства": "分辨材料并比较它们的特性",
"Рассказывают, из чего и как сделана работа.": "讲讲作品是用什么、怎样做成的。",
"Рваная аппликация: бумагу рвут на кусочки и наклеивают. Так получаются облака и трава.": "撕纸贴画：把纸撕成小块再贴上去。这样就能做出云朵和草地。",
