"Симметричный узор одинаковый с обеих сторон от середины.": "对称图案从中间向两边是一样的。",
"Скотч": "胶带",
"Сначала карандашом ставят точки и проводят линии по линейке. Потом вырезают.": "先用铅笔点点，再沿着尺子画线。然后剪下来。",
"Сначала придумывают идею, выбирают материалы и рисуют эскиз.": "先想出创意，选择材料，画出草图。",
"Собирать и готовить природные и бросовые материалы": "收集并准备天然材料和废旧材料",
"Советы помогают исправить недочёты и сделать работу лучше.": "建议帮助改正缺点，把作品做得更好。",
"Сырмак — войлочный ковёр с узором из кусочков войлока.": "绣花毡是用毛毡小块拼成图案的毛毡地毯。",
"Ткань мягкая. Её режут ножницами и сшивают иглой с ниткой.": "布很软。用剪刀剪，用针线缝。",
