"Бабочка откладывает яйца. Из яйца выходит гусеница. Гусеница превращается в куколку, а из куколки выходит бабочка.": "蝴蝶产卵。从卵里出来毛毛虫。毛毛虫变成蛹，从蛹里出来蝴蝶。",
