"Гепард, самолёт и ракета движутся быстро. Они проходят большое расстояние за короткое время.": "猎豹、飞机和火箭运动得很快。它们在很短时间内走过很长的距离。",
"Гипотеза — наше предположение. Например: «Камень утонет, а деревянный брусок нет». Опыт покажет, верно ли оно.": "假设是我们的猜测。例如：“石头会沉下去，而木块不会。”实验会显示它对不对。",
"Глину добывают из земли.": "黏土是从地里挖出来的。",
