"Делаем выводы по дневнику": "我们根据日记得出结论",
"Дерево магнит не притягивает.": "磁铁不吸木头。",
"Дерево не пропускает свет.": "木头不让光通过。",
"Дерево, стекло, пластмасса и бумага к магниту не притягиваются.": "木头、玻璃、塑料和纸都不被磁铁吸引。",
"Деревья, кустарники, травы": "乔木、灌木、草",
"Для роста нужно тепло. Семена прорастают в тёплой земле.": "生长需要温暖。种子在温暖的土里发芽。",
"Для роста растению нужен свет.": "植物生长需要光。",
