"Дождь и снег — тоже источники воды. Подземную воду достают из колодцев.": "雨和雪也是水的来源。地下水从水井里取出。",
"Древесина, хлопок, зерно, овощи. Из них делают бумагу, мебель, ткани и еду.": "木材、棉花、粮食、蔬菜。用它们制造纸、家具、布料和食物。",
"Древесину получают от деревьев.": "木材来自树木。",
