"Единицы времени расставлены верно.": "时间单位排列正确。",
"Если пар из воздуха попадёт на холодный стакан, он превратится в капельки воды.": "如果空气中的水蒸气碰到冷杯子，就会变成小水珠。",
"Если пустой стакан вверх дном опустить в воду, вода не зайдёт внутрь. Место занимает воздух.": "如果把空杯子倒扣着放进水里，水不会进到里面。空气占着位置。",
"Если тело меняет своё место, значит оно движется.": "如果物体改变了自己的位置，就说明它在运动。",
"Железо притягивается магнитом.": "铁被磁铁吸引。",
"Животным вредят браконьеры, вырубка лесов, пожары, загрязнение воды и мусор.": "偷猎者、砍伐森林、火灾、水污染和垃圾危害动物。",
"Животных делят на группы — классы — по общим признакам. Нажимай на карточки.": "动物按共同特征分成组——纲。点一点卡片。",
"Журавли улетают на зиму.": "鹤冬天飞走。",
"Жёлтая книга": "黄皮书",
