"За какое время Земля делает один оборот вокруг своей оси?": "地球绕自己的轴转一圈需要多长时间？",
"За почвой ухаживают: рыхлят, поливают, удобряют. Тогда растения получают питание.": "要照料土壤：松土、浇水、施肥。这样植物才能得到营养。",
