"Здоровье зависит от привычек. Нажимай на карточки.": "健康取决于习惯。点一点卡片。",
"Зелёная тетрадь": "绿色练习本",
"Земля вращается вокруг своей оси": "地球绕自己的轴转动",
"Земля вращается вокруг своей оси. Один оборот — сутки. Сторона, которую освещает Солнце, — день. Другая сторона — ночь.": "地球绕自己的轴转动。转一圈是一天。被太阳照亮的一面是白天，另一面是黑夜。",
"Земля летит вокруг Солнца. Один оборот — год. Это около трёхсот шестидесяти пяти суток.": "地球绕太阳运行。转一圈是一年。这大约是三百六十五天。",
"Земля притягивает все тела. Поэтому яблоко падает вниз, а реки текут вниз.": "地球吸引所有物体。所以苹果向下落，河水向下流。",
"Земля то приближается, то удаляется": "地球时而靠近，时而远离",
"Земля — каменная планета.": "地球是岩石行星。",
"Земля — планета. Она третья от Солнца. На ней есть воздух, вода и жизнь.": "地球是行星。它是距太阳第三颗。上面有空气、水和生命。",
"Земля — третья планета. На ней есть жизнь.": "地球是第三颗行星。上面有生命。",
"Земля, Солнце и Луна": "地球、太阳和月亮",
"Земля, Солнце и Луна связаны между собой. Нажимай на карточки.": "地球、太阳和月亮互相联系。点一点卡片。",
"Земля, Солнце, Луна": "地球、太阳、月亮",
"Зимой дерево стоит без листьев и отдыхает": "冬天树没有叶子，在休息",
"Зимой деревья без листьев отдыхают. Многие травы спрятались под снег. Ель и сосна остаются зелёными.": "冬天树没有叶子，在休息。许多草藏在雪下。云杉和松树仍然是绿的。",
"Зимой корма мало. Медведь, ёж и барсук проводят зиму в спячке.": "冬天食物少。熊、刺猬和獾冬眠度过冬天。",
"Зимой шерсть зайца-беляка становится белой.": "冬天雪兔的毛变成白色。",
"Змея — пресмыкающееся.": "蛇是爬行动物。",
