"Исследователь аккуратно обращается с приборами и точно записывает всё, что увидел.": "探索者小心地使用仪器，准确记录所看到的一切。",
"Исследователь внимательно смотрит, слушает и замечает мелочи.": "探索者仔细看、仔细听，注意小细节。",
"Исследователь всё время спрашивает: «почему?» и «как?». Какое это качество?": "探索者总是问：“为什么？”“怎么样？”这是什么品质？",
"Исследователь замечает мелкие изменения. Какое качество ему нужно?": "探索者会注意到细小的变化。他需要什么品质？",
