"Исследователь записывает то, что хочет увидеть, а не то, что видит.": "探索者记录自己想看到的，而不是看到的。",
"Исследователь изучает мир вокруг. Чтобы у него получалось, нужны особые качества. Нажимай на карточки.": "探索者研究周围的世界。要做好，需要特别的品质。点一点卡片。",
"Исследователь любознательный. Он спрашивает: почему? как? что будет, если…?": "探索者有好奇心。他问：为什么？怎么样？如果……会怎样？",
"Исследователь сдаётся сразу, если опыт не получился.": "如果实验没成功，探索者马上就放弃。",
