"💡 Вода принимает форму сосуда.": "💡 水呈现容器的形状。",
"💡 Воду растение берёт корнями.": "💡 植物用根吸水。",
"💡 Водяной пар — вода в виде газа.": "💡 水蒸气是气体状态的水。",
"💡 Воздух есть везде: даже в «пустом» стакане.": "💡 空气到处都有：连“空”杯子里也有。",
