"💡 Воздух плохо проводит тепло. Двойные окна сохраняют тепло.": "💡 空气不容易传热。双层窗保持温暖。",
"💡 Воздух прозрачный и бесцветный.": "💡 空气透明无色。",
"💡 Воздух прозрачный. Небо кажется голубым, но сам воздух бесцветный.": "💡 空气是透明的。天空看起来是蓝色，但空气本身是无色的。",
