"Чтобы быстро записывать, используют условные знаки: солнышко — ясно, облако — облачно, тучка с каплями — дождь, снежинка — снег.": "为了快速记录，使用符号：小太阳——晴，云——多云，带水滴的小云——下雨，雪花——下雪。",
"Чтобы выжить, животные приспосабливаются к тому месту, где живут. Нажимай на карточки.": "为了生存，动物适应自己生活的地方。点一点卡片。",
"Чтобы кости и мышцы были крепкими, нужно двигаться, заниматься спортом и есть полезную еду.": "要让骨头和肌肉强壮，需要运动、做体育活动并吃有益的食物。",
