"Чтобы растение выросло, ему нужны определённые условия. Нажимай на карточки.": "植物要长大，需要一定的条件。点一点卡片。",
"Чтобы увидеть результат, часто нужно подождать. Растение не вырастет за один день.": "要看到结果，常常需要等待。植物不会一天就长大。",
